"""Original SLE questions: treatment, nephritis and pregnancy planning."""
from create_rheum_lupus_diagnosis import rows,q,C,S,E,N,K,ref
H=ref('AAO hydroxychloroquine retinal screening: 2025 revision','https://www.aao.org/education/clinical-statement/revised-recommendations-on-screening-chloroquine-h')
P=ref('EULAR antirheumatic drugs in reproduction/pregnancy: 2024 update','https://pubmed.ncbi.nlm.nih.gov/40287311/')

q('Which medication is generally recommended as background therapy for SLE unless contraindicated?', 'Hydroxychloroquine',[
 ('Cyclophosphamide','This is reserved for selected severe organ-threatening disease rather than universal background treatment.'),('Warfarin','Anticoagulation requires an appropriate indication, such as thrombotic APS.'),('Indomethacin','An NSAID may provide selected symptom relief but is not equivalent background disease modification.')],
 'Maintain an effective low-toxicity foundation','**Hydroxychloroquine is recommended for most patients with SLE unless contraindicated.**',['Benefits extend beyond immediate symptom relief and include reduced flare risk.','Dose selection should balance disease control with retinal risk and other patient factors.'], '**Review adherence, actual body weight and renal function.**',['Arrange baseline and ongoing retinal monitoring according to current recommendations.','Do not use the same unreviewed fixed dose for every body weight.'],[['Hydroxychloroquine','Background treatment'],['Cyclophosphamide','Selected severe disease'],['Anticoagulation','Separate thrombotic indication']],[S,E,H])

q('A patient with SLE remains on prednisone 15 mg/day for recurrent arthritis despite hydroxychloroquine. What is the preferred long-term direction?', 'Introduce or optimize steroid-sparing therapy and taper glucocorticoids toward a minimal dose or withdrawal',[
 ('Maintain 15 mg indefinitely because musculoskeletal disease has no alternatives','Persistent exposure increases harm and effective steroid-sparing options exist.'),('Stop prednisone abruptly after years of use without an adrenal or flare plan','Abrupt withdrawal can cause adrenal insufficiency and disease recurrence.'),('Replace hydroxychloroquine with a chronic NSAID alone regardless of active disease','This does not provide an adequate disease-modifying strategy for persistent inflammatory disease.')],
 'Reduce cumulative glucocorticoid harm','**Contemporary SLE guidance emphasizes early steroid-sparing treatment and the lowest feasible glucocorticoid exposure.**',['Use a taper matched to activity, duration of exposure and adrenal risk.','Persistent arthritis can justify a conventional immunosuppressant or biologic according to the treatment pathway.'], '**Assess whether residual pain is inflammatory before escalation.**',['Monitor infection, bone, metabolic and cardiovascular risks.','Avoid regarding chronic glucocorticoids as a harmless substitute for effective maintenance therapy.'],[['Persistent inflammatory arthritis','Optimize disease modification'],['Chronic prednisone','Cumulative toxicity'],['Taper','Disease and adrenal considerations']],[S,E],style='clinical_scenario')

q('Which biological mechanism is targeted by belimumab?', 'BAFF/BLyS-dependent B-cell survival signaling',[
 ('The type I interferon receptor','This is the target of anifrolumab.'),('CD20 with direct B-cell depletion','This is the target of rituximab and obinutuzumab, with differing antibody properties.'),('The IL-6 receptor','This is targeted by tocilizumab and sarilumab.')],
 'Distinguish B-cell support inhibition from depletion','**Belimumab inhibits soluble BAFF, also called BLyS.**',['It can be added for appropriate active SLE and lupus nephritis settings.','Clinical response is not equivalent to immediate complete B-cell depletion.'], '**Select it for the disease domain and combination strategy.**',['Review infection, mental health and other relevant safety concerns.','An antibody mechanism does not by itself establish efficacy in every lupus organ manifestation.'],[['Belimumab','BAFF/BLyS'],['Anifrolumab','Type I IFN receptor'],['Obinutuzumab','CD20']],[ref('FDA belimumab prescribing information','https://www.accessdata.fda.gov/drugsatfda_docs/label/2020/125370s073,761043s013lbl.pdf')])

q('Which mechanism best describes anifrolumab?', 'Blockade of the type I interferon receptor',[
 ('Neutralization of BAFF','This describes belimumab.'),('Inhibition of calcineurin','This describes drugs such as tacrolimus or voclosporin.'),('Depletion of CD20-positive B cells','This describes anti-CD20 antibodies rather than anifrolumab.')],
 'Target the interferon pathway','**Anifrolumab binds the type I interferon receptor and inhibits its signaling.**',['It is used with standard therapy for appropriate moderate-to-severe SLE.','Its efficacy in severe active lupus nephritis or severe active CNS lupus has not been established in the product indication.'], '**Do not extrapolate a general SLE indication to every severe organ syndrome.**',['Review infection and herpes zoster risk.','Choose a treatment with evidence for the organ involvement being treated.'],[['Anifrolumab','Type I interferon receptor'],['Belimumab','BAFF'],['Voclosporin','Calcineurin']],[ref('DailyMed Saphnelo prescribing information','https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=d6203302-2128-41a7-b0b4-0e6c0704d4dc&type=display')])

q('An SLE patient has newly sustained urine protein/creatinine ratio 0.9 g/g, dysmorphic erythrocytes and an unexplained creatinine rise. Which investigation is most informative for selecting renal immunosuppression?', 'Kidney biopsy, if there is no prohibitive contraindication',[
 ('Anti-dsDNA titer alone','It cannot determine histological class, chronicity or all alternative renal lesions.'),('Renal ultrasound alone','It assesses structure and obstruction but does not classify lupus nephritis.'),('A repeat ANA titer alone','ANA is not a renal pathology classification test.')],
 'Renal histology changes treatment','**Biopsy defines the pattern and activity of renal injury.**',['Relevant findings include proliferative lesions, membranous deposits, chronic damage and vascular/TMA lesions.','Current guidelines support biopsy with clinically important proteinuria and/or otherwise unexplained renal impairment.'], '**Assess safety before biopsy and avoid unnecessary delay in a rapidly deteriorating patient.**',['Measure blood pressure, platelets and coagulation and review anticoagulants.','Continue parallel evaluation of infection, medications and other renal causes.'],[['Serology','Supporting context'],['Ultrasound','Anatomical assessment'],['Biopsy','Class, activity, chronicity and alternative pathology']],[N,K],style='clinical_scenario')

q('Which biopsy pattern defines class IV lupus nephritis in the conventional ISN/RPS classification?', 'Proliferative glomerular lesions involving at least 50% of glomeruli',[
 ('Proliferative lesions involving fewer than 50% of glomeruli','This describes class III focal lupus nephritis.'),('Predominantly subepithelial membranous deposits without the stated proliferative extent','This describes class V rather than the defining class IV pattern.'),('Mesangial immune deposits without light-microscopic abnormalities','This corresponds to minimal mesangial class I disease.')],
 'Distinguish focal from diffuse proliferative disease','**Class IV denotes diffuse involvement of at least half the sampled glomeruli.**',['The biopsy also reports activity and chronicity rather than a class label alone.','Mixed proliferative and membranous lesions can occur.'], '**Base management on histology, renal function and the complete clinical picture.**',['Active lesions may respond to immunosuppression.','Extensive chronic sclerosis predicts a different potential for reversibility.'],[['Class III','<50% proliferative involvement'],['Class IV','At least 50%'],['Class V','Membranous pattern']],[K])

q('A patient has active class IV lupus nephritis. Which regimen is a conditionally recommended initial triple-therapy option in the 2024 ACR nephritis guideline?', 'Glucocorticoids plus mycophenolate plus belimumab',[
 ('Hydroxychloroquine plus aspirin plus an NSAID','This is not sufficient treatment for active proliferative nephritis.'),('Azathioprine plus warfarin plus colchicine','This does not match a recommended initial proliferative-nephritis triple regimen.'),('Anifrolumab plus abatacept plus prednisone','This is not the guideline-supported triple regimen and combines unsupported advanced agents.')],
 'Recognize the recommended combination structure','**ACR triple therapy combines glucocorticoids with two selected immunosuppressive agents.**',['Options include mycophenolate plus belimumab or a calcineurin inhibitor, and a low-dose IV cyclophosphamide/belimumab pathway.','The choice depends on kidney function, proteinuria, extrarenal disease, prior treatment and patient preferences.'], '**Use a planned glucocorticoid taper and maintenance strategy.**',['Monitor infection and drug-specific toxicity.','Newer evidence and approvals must be interpreted alongside the date and jurisdiction of the cited guideline.'],[['GC + mycophenolate + belimumab','ACR initial option'],['GC + mycophenolate + CNI','Another option'],['Regimen choice','Individual renal and systemic factors']],[N],style='clinical_scenario')

q('Which mechanism most directly explains voclosporin action in lupus nephritis?', 'Calcineurin inhibition',[
 ('CD20-positive B-cell depletion','This describes anti-CD20 therapy.'),('BAFF neutralization','This describes belimumab.'),('Inosine monophosphate dehydrogenase inhibition','This describes mycophenolic acid action.')],
 'Know the CNI component of a renal combination','**Voclosporin is a calcineurin inhibitor used in an appropriate lupus nephritis regimen.**',['Calcineurin inhibitors have immunological and podocyte-related antiproteinuric effects.','Reduced proteinuria does not eliminate the need to monitor filtration and systemic disease.'], '**Review baseline renal function and drug interactions before treatment.**',['Monitor eGFR, blood pressure and potassium according to the product and regimen.','Avoid extrapolation to markedly impaired renal function without specialist assessment.'],[['Voclosporin','Calcineurin'],['Mycophenolate','Purine synthesis pathway'],['Belimumab','B-cell survival signal']],[K,ref('FDA voclosporin prescribing information','https://www.accessdata.fda.gov/drugsatfda_docs/label/2021/213716s000lbl.pdf')])

q('A patient with active lupus nephritis asks about obinutuzumab. Which statement reflects its established mechanism and current US role?', 'It is a type II anti-CD20 antibody approved with standard therapy for adults with active lupus nephritis',[
 ('It is a BAFF inhibitor approved only for skin disease','Its target is CD20 and its role now includes adult active nephritis.'),('It is an IL-17 inhibitor with no renal lupus trial evidence','This misidentifies both the mechanism and evidence.'),('It is a calcineurin inhibitor that requires no infection screening','It is B-cell-depleting therapy with relevant infection and HBV precautions.')],
 'Account for evidence and approvals after older guideline cutoffs','**Obinutuzumab depletes CD20-positive B cells and has an adult lupus nephritis indication in the US.**',['The REGENCY trial showed improved renal responses when it was added to standard therapy.','A drug absent from an older first-line guideline is not necessarily absent from current evidence or approvals.'], '**Apply the current label and local access framework.**',['Screen for hepatitis B and review infection and vaccination risks.','Coordinate infusion precautions, blood count monitoring and the background immunosuppressive regimen.'],[['Target','CD20'],['Current adult renal indication','With standard therapy'],['Safety','HBV/infection and infusion precautions']],[ref('DailyMed Gazyva prescribing information, updated September 2026','https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=df12ceb2-5b4b-4ab5-a317-2a36bf2a3cda'),ref('REGENCY original trial','https://www.nejm.org/doi/full/10.1056/NEJMoa2410965')],style='clinical_scenario')

q('A woman with lupus nephritis is taking mycophenolate and plans pregnancy. Which change is essential to discuss before conception?', 'Replace mycophenolate with a suitable pregnancy-compatible regimen and establish stable disease control',[
 ('Continue mycophenolate unchanged because renal disease removes fetal risk','Mycophenolate is associated with pregnancy loss and congenital malformations.'),('Replace it with methotrexate','Methotrexate is also unsuitable for planned pregnancy.'),('Stop all renal follow-up once the medication is changed','Lupus nephritis and pregnancy require careful ongoing monitoring.')],
 'Plan both fetal safety and renal stability','**Mycophenolate is not pregnancy-compatible.**',['Azathioprine and selected calcineurin inhibitor regimens can be alternatives when appropriate.','Conception is preferably planned during a period of stable, controlled disease.'], '**Do not substitute medications without monitoring the renal response.**',['Review blood pressure drugs, anticoagulation and other exposures as well.','Coordinate maternal-fetal medicine, nephrology and rheumatology care.'],[['Mycophenolate','Pregnancy risk'],['Azathioprine/selected CNI','Potential alternatives'],['Disease stability','Important before conception']],[P,N],style='clinical_scenario')

q('After initial treatment of proliferative lupus nephritis, which finding best supports a favorable renal response?', 'Substantial proteinuria reduction together with stable or improving kidney function',[
 ('ANA becoming negative regardless of urine findings','ANA normalization is not the renal response target.'),('Complement normalization despite rising creatinine and proteinuria','Serology cannot override worsening objective renal findings.'),('Less ankle edema while proteinuria and creatinine worsen','Symptom improvement alone does not establish renal response.')],
 'Track the kidney, not only the antibodies','**Protein excretion and kidney function are central response measures.**',['The trajectory and timing depend on baseline severity and the regimen.','Serology, blood pressure, urine sediment and adherence add context.'], '**Investigate an inadequate or discordant response.**',['Check dose, exposure, adherence and alternative renal injury.','Repeat biopsy can be useful when activity versus chronic damage or another process remains uncertain.'],[['Proteinuria','Key response trajectory'],['eGFR/creatinine','Functional outcome'],['Serology','Supporting information']],[K,N])

q('A patient has persistent proteinuria despite nephritis treatment. A repeat biopsy shows mostly glomerulosclerosis and interstitial fibrosis with little active inflammation. What does this imply?', 'Chronic damage may be the main driver, so more immunosuppression may add harm without equivalent benefit',[
 ('All persistent proteinuria proves uncontrolled immune inflammation','Structural damage can maintain proteinuria despite control of activity.'),('The biopsy is irrelevant if anti-dsDNA remains positive','Histological context matters and antibodies alone do not define reversibility.'),('Renoprotective and blood-pressure management should be stopped','Supportive CKD care remains important even when inflammation is limited.')],
 'Distinguish activity from chronicity','**Immunosuppression treats active immune injury more effectively than established fibrosis.**',['Persistent proteinuria can reflect residual damage, ongoing activity or another renal process.','Biopsy and clinical trends can prevent unnecessary escalation.'], '**Optimize kidney-protective care and reassess the overall regimen.**',['Manage blood pressure and proteinuria with appropriate medications and monitoring.','Avoid presenting chronic scarring as reversible simply by increasing glucocorticoids.'],[['Active lesions','Potentially immunosuppression-responsive'],['Fibrosis/sclerosis','Limited reversibility'],['Supportive care','Remains essential']],[K,N],style='clinical_scenario')

q('Which lupus nephritis biopsy class corresponds to predominantly membranous glomerular immune deposition?', 'Class V',[
 ('Class II','This is mesangial proliferative disease.'),('Class III','This is focal proliferative nephritis.'),('Class VI','This is advanced sclerosing nephritis.')],
 'Membranous lupus nephritis has a distinct clinical pattern','**Class V is the membranous pattern and often presents with significant proteinuria.**',['It can coexist with class III or IV lesions.','The amount of proteinuria, kidney function and mixed pathology affect treatment.'], '**Do not treat all biopsy classes as interchangeable.**',['Nephrotic syndrome brings thrombotic and infection risks requiring assessment.','Mixed proliferative disease usually requires a proliferative-nephritis strategy.'],[['Class II','Mesangial proliferative'],['Class V','Membranous'],['Class VI','Advanced sclerosis']],[K])

q('A patient with active severe lupus nephritis is considering cyclophosphamide. Which additional counseling is particularly important?', 'Fertility preservation and cumulative gonadal, bladder and marrow toxicity',[
 ('Retinal screening as the unique dose-limiting cyclophosphamide concern','Retinal toxicity is principally a hydroxychloroquine issue, not the defining cyclophosphamide counseling point.'),('The absence of any infection risk because courses can be short','Cyclophosphamide can cause serious infection and cytopenias.'),('Permanent contraception is unnecessary because alkylating drugs have no reproductive effects','There are substantial fertility and pregnancy risks.')],
 'Discuss irreversible risks before an alkylating agent','**Cyclophosphamide can impair fertility, with risk related to age, dose and exposure.**',['Consider fertility preservation and gonadal protection strategies when appropriate without delaying urgent life-saving care.','Blood counts, infection prevention and uroprotection depend on the regimen.'], '**Use an evidence-based dose strategy for the clinical severity.**',['Review alternatives and patient preferences.','Monitor cumulative exposure and transition to an appropriate maintenance plan.'],[['Gonadal risk','Discuss preservation/protection'],['Marrow risk','Blood count monitoring'],['Bladder risk','Regimen-specific prevention and evaluation']],[K,P],style='clinical_scenario')

q('A pregnant patient with SLE develops hypertension and proteinuria. Which combination more strongly supports active lupus nephritis than isolated preeclampsia?', 'Active glomerular sediment with falling complement and rising anti-dsDNA',[
 ('New hypertension after 20 weeks without active sediment or serological change','This can fit preeclampsia, though the complete maternal assessment is still required.'),('Isolated elevation of uric acid','This is nonspecific and can accompany preeclampsia or renal dysfunction.'),('Peripheral edema without urinary or serological characterization','Edema is nonspecific in pregnancy.')],
 'Lupus nephritis and preeclampsia may overlap','**Active sediment and lupus serological activity favor renal immune inflammation.**',['Complement interpretation in pregnancy requires awareness of expected physiological changes and trends.','No single test reliably separates every case, and both conditions can coexist.'], '**Coordinate urgent maternal and fetal assessment.**',['Review gestational timing, organ dysfunction, medication exposure and fetal status.','The distinction matters because obstetric and immunosuppressive treatments differ.'],[['Active sediment','Supports glomerular inflammation'],['Complement/dsDNA trend','Supports lupus activity'],['Overlap','Both diagnoses may be present']],[N,P],style='clinical_scenario')

q('Which medication is generally compatible with pregnancy and is usually continued for SLE disease control unless contraindicated?', 'Hydroxychloroquine',[
 ('Mycophenolate mofetil','It is associated with fetal risk and is unsuitable for planned pregnancy.'),('Methotrexate','It is unsuitable for planned pregnancy.'),('Leflunomide without elimination planning','It requires appropriate discontinuation and clearance planning rather than routine pregnancy continuation.')],
 'Avoid unnecessary withdrawal of a compatible protective treatment','**Hydroxychloroquine is generally continued during SLE pregnancy.**',['Maintaining disease control is important for maternal and fetal outcomes.','Other drugs require an individualized compatibility review.'], '**Plan pregnancy before conception when possible.**',['Assess nephritis activity, aPL status and anti-Ro/La antibodies.','Coordinate monitoring and adjust incompatible medications in advance.'],[['Hydroxychloroquine','Usually compatible'],['Mycophenolate/methotrexate','Not compatible'],['Preconception review','Disease activity and full medication list']],[P,S])

